package app.quietkey;

import org.junit.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.Assert.*;

public final class LocalJoinTest {
    private static KeyPair a,b,c;
    @BeforeClass public static void keys()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);a=g.generateKeyPair();b=g.generateKeyPair();c=g.generateKeyPair();}
    private static byte[] encoded(int type,String packet,byte[] key)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(LocalJoinWire wire=new LocalJoinWire(new ByteArrayInputStream(new byte[0]),out,type!=LocalJoinWire.REQUEST,key)){wire.send(type,packet);}return out.toByteArray();}
    private static LocalJoinWire read(byte[] frame,byte[] key){return new LocalJoinWire(new ByteArrayInputStream(frame),new ByteArrayOutputStream(),true,key);}
    @Test public void oneTimeCodesNormalizeAndRemainDistinct()throws Exception{Set<String> codes=new HashSet<>();for(int i=0;i<500;i++){String code=LocalJoinWire.newCode();assertTrue(code.matches("[2-9A-HJ-NP-Z]{4}(-[2-9A-HJ-NP-Z]{4}){4}"));assertTrue(codes.add(code));assertArrayEquals(LocalJoinWire.codeKey(code),LocalJoinWire.codeKey(code.toLowerCase(Locale.ROOT).replace('-',' ')));}assertThrows(IllegalArgumentException.class,()->LocalJoinWire.codeKey("123456"));assertThrows(IllegalArgumentException.class,()->LocalJoinWire.codeKey("IIII-IIII-IIII-IIII-IIII"));}
    @Test public void onlyLiteralPrivateIpv4EndpointsAllowed(){for(String s:new String[]{"192.168.43.1","10.0.2.15","172.16.0.1","172.31.255.2"})assertTrue(s,LocalJoinWire.privateAddress(s));for(String s:new String[]{"127.0.0.1","localhost","example.com","8.8.8.8","169.254.1.1","172.32.0.1","192.168.1.256","192.168.0.0","192.168.1.255","10.0.0.1:80","10.1.2.3/24","10.1.2.-1",null})assertFalse(s,LocalJoinWire.privateAddress(s));}
    @Test public void encryptedRequestHidesMetadataAndRejectsWrongCode()throws Exception{String request=PairingProtocol.request(b.getPublic(),b.getPrivate(),"Secret-device-name");byte[] key=LocalJoinWire.codeKey(LocalJoinWire.newCode()),frame=encoded(LocalJoinWire.REQUEST,request,key);assertFalse(new String(frame,java.nio.charset.StandardCharsets.ISO_8859_1).contains("QKJ1:"));try(LocalJoinWire wire=read(frame,key)){assertEquals(request,wire.receive(LocalJoinWire.REQUEST));}try(LocalJoinWire wire=read(frame,LocalJoinWire.codeKey(LocalJoinWire.newCode()))){assertThrows(Exception.class,()->wire.receive(LocalJoinWire.REQUEST));}}
    @Test public void tamperedCipherAndDowngradeFail()throws Exception{byte[] key=LocalJoinWire.codeKey(LocalJoinWire.newCode());byte[] frame=encoded(LocalJoinWire.REQUEST,"QKJ1:abc",key);frame[frame.length-1]^=1;try(LocalJoinWire wire=read(frame,key)){assertThrows(Exception.class,()->wire.receive(LocalJoinWire.REQUEST));}frame[4]=0;try(LocalJoinWire wire=read(frame,key)){assertThrows(SecurityException.class,()->wire.receive(LocalJoinWire.REQUEST));}try(LocalJoinWire wire=read(encoded(LocalJoinWire.REQUEST,"QKJ1:abc",null),key)){assertThrows(SecurityException.class,()->wire.receive(LocalJoinWire.REQUEST));}}
    @Test public void oversizedNegativeTruncatedAndNonAsciiFail()throws Exception{for(int size:new int[]{-1,30029,Integer.MAX_VALUE}){ByteArrayOutputStream raw=new ByteArrayOutputStream();DataOutputStream o=new DataOutputStream(raw);o.writeInt(0x454A5731);o.writeByte(0);o.writeByte(1);o.writeInt(0);o.writeInt(size);try(LocalJoinWire wire=read(raw.toByteArray(),null)){assertThrows(SecurityException.class,()->wire.receive(1));}}
        byte[] valid=encoded(1,"QKJ1:abc",null);try(LocalJoinWire wire=read(Arrays.copyOf(valid,valid.length-1),null)){assertThrows(EOFException.class,()->wire.receive(1));}valid[valid.length-1]=(byte)255;try(LocalJoinWire wire=read(valid,null)){assertThrows(SecurityException.class,()->wire.receive(1));}
        assertThrows(SecurityException.class,()->encoded(1,"QKJ1:é",null));assertThrows(SecurityException.class,()->encoded(1,"QKJ1:"+"a".repeat(1600),null));}
    @Test public void replayAndWrongStepsFail()throws Exception{byte[] valid=encoded(1,"QKJ1:abc",null);ByteArrayOutputStream doubled=new ByteArrayOutputStream();doubled.write(valid);doubled.write(valid);try(LocalJoinWire wire=read(doubled.toByteArray(),null)){assertEquals("QKJ1:abc",wire.receive(1));assertThrows(SecurityException.class,()->wire.receive(3));}try(LocalJoinWire wire=read(valid,null)){assertThrows(SecurityException.class,()->wire.send(1,"QKJ1:abc"));assertThrows(SecurityException.class,()->wire.receive(3));}}
    private void exchange(boolean encrypted,boolean fragmented)throws Exception{
        Protocol.Group group=Protocol.create("Nearby group",Protocol.random(32),a.getPublic());String request=PairingProtocol.request(b.getPublic(),b.getPrivate(),"Recipient");
        Set<String> used=new LinkedHashSet<>();Map<String,String> pending=new LinkedHashMap<>();Map<String,JoiningFlow.Invitation> cache=new LinkedHashMap<>();Protocol.Group[] joined={null};AtomicInteger ownerCalls=new AtomicInteger(),joinCalls=new AtomicInteger();String[] invitation={null};
        LocalJoinSession.Approval approval=new LocalJoinSession.Approval(){
            public CompletableFuture<String> invite(String r){ownerCalls.incrementAndGet();try{invitation[0]=JoiningFlow.invite(group,r,a.getPublic(),a.getPrivate(),used,pending,cache);return CompletableFuture.completedFuture(invitation[0]);}catch(Exception e){return CompletableFuture.failedFuture(e);}}
            public CompletableFuture<String> accept(String grant){joinCalls.incrementAndGet();try{joined[0]=PairingProtocol.accept(grant,request,b.getPublic(),b.getPrivate());return CompletableFuture.completedFuture(PairingProtocol.receipt(joined[0],PairingProtocol.parseRequest(request).id,b.getPublic(),b.getPrivate()));}catch(Exception e){return CompletableFuture.failedFuture(e);}}
            public CompletableFuture<Void> receipt(String receipt){try{PairingProtocol.receiptMember(group,receipt,pending);return CompletableFuture.completedFuture(null);}catch(Exception e){return CompletableFuture.failedFuture(e);}}
            public void status(String text){}
        };
        byte[] key=encrypted?LocalJoinWire.codeKey(LocalJoinWire.newCode()):null;ExecutorService pool=Executors.newSingleThreadExecutor();
        try(ServerSocket listener=new ServerSocket(0,1,InetAddress.getLoopbackAddress())){
            Future<?> owner=pool.submit(()->{try(Socket socket=listener.accept()){socket.setSoTimeout(5000);InputStream in=socket.getInputStream();if(fragmented)in=new FilterInputStream(in){public int read(byte[] buf,int off,int len)throws IOException{return super.read(buf,off,Math.min(len,3));}};try(LocalJoinWire wire=new LocalJoinWire(in,socket.getOutputStream(),true,key)){LocalJoinSession.exchange(wire,true,null,approval,System.nanoTime()+TimeUnit.SECONDS.toNanos(10));}}catch(Exception e){throw new CompletionException(e);}});
            try(Socket socket=new Socket(InetAddress.getLoopbackAddress(),listener.getLocalPort());LocalJoinWire wire=new LocalJoinWire(socket.getInputStream(),socket.getOutputStream(),false,key)){socket.setSoTimeout(5000);LocalJoinSession.exchange(wire,false,request,approval,System.nanoTime()+TimeUnit.SECONDS.toNanos(10));}
            owner.get(10,TimeUnit.SECONDS);
        }finally{pool.shutdownNow();}
        assertEquals(1,ownerCalls.get());assertEquals(1,joinCalls.get());assertEquals(group.members,joined[0].members);assertArrayEquals(group.seed,joined[0].seed);assertEquals("Joined",group.memberStatus.get(Protocol.fingerprint(b.getPublic())));assertTrue(pending.isEmpty());assertThrows(Exception.class,()->PairingProtocol.accept(invitation[0],request,c.getPublic(),c.getPrivate()));
        String message=DirectProtocol.encrypt(group,Protocol.fingerprint(b.getPublic()),"First message after joining",a.getPublic(),a.getPrivate());
        assertEquals("First message after joining",DirectProtocol.decrypt(joined[0],message,b.getPublic(),b.getPrivate()).text);
        String reply=DirectProtocol.encrypt(joined[0],Protocol.fingerprint(a.getPublic()),"Reply from B",b.getPublic(),b.getPrivate());assertEquals("Reply from B",DirectProtocol.decrypt(group,reply,a.getPublic(),a.getPrivate()).text);
    }
    @Test public void encryptedTcpJoinsAndReturnsVerifiedReceipt()throws Exception{exchange(true,false);}
    @Test public void cableStyleFragmentedDuplexJoinsAndReturnsReceipt()throws Exception{exchange(false,true);}
    @Test public void invalidSignatureNeverReachesOwnerConsent()throws Exception{String request=PairingProtocol.request(b.getPublic(),b.getPrivate(),"B");byte[] raw=Protocol.un64(request.substring(5));raw[raw.length-1]^=1;byte[] framed=encoded(1,"QKJ1:"+Protocol.b64(raw),null);AtomicInteger calls=new AtomicInteger();try(LocalJoinWire wire=read(framed,null)){assertThrows(Exception.class,()->LocalJoinSession.exchange(wire,true,null,new LocalJoinSession.Approval(){public CompletableFuture<String> invite(String r){calls.incrementAndGet();return CompletableFuture.completedFuture("QKG2:abc");}public CompletableFuture<String> accept(String i){throw new AssertionError();}public CompletableFuture<Void> receipt(String r){throw new AssertionError();}public void status(String text){}},System.nanoTime()+TimeUnit.SECONDS.toNanos(1)));}assertEquals(0,calls.get());}
    @Test public void ownerDeclineProducesNoInvitation()throws Exception{byte[] framed=encoded(1,PairingProtocol.request(b.getPublic(),b.getPrivate(),"B"),null);ByteArrayOutputStream sent=new ByteArrayOutputStream();try(LocalJoinWire wire=new LocalJoinWire(new ByteArrayInputStream(framed),sent,true,null)){assertThrows(ExecutionException.class,()->LocalJoinSession.exchange(wire,true,null,new LocalJoinSession.Approval(){public CompletableFuture<String> invite(String r){return CompletableFuture.failedFuture(new SecurityException("Declined"));}public CompletableFuture<String> accept(String i){throw new AssertionError();}public CompletableFuture<Void> receipt(String r){throw new AssertionError();}public void status(String text){}},System.nanoTime()+TimeUnit.SECONDS.toNanos(1)));}assertEquals(0,sent.size());}
    @Test public void consentTimesOutWithoutSendingGroupDetails()throws Exception{byte[] framed=encoded(1,PairingProtocol.request(b.getPublic(),b.getPrivate(),"B"),null);ByteArrayOutputStream sent=new ByteArrayOutputStream();try(LocalJoinWire wire=new LocalJoinWire(new ByteArrayInputStream(framed),sent,true,null)){assertThrows(TimeoutException.class,()->LocalJoinSession.exchange(wire,true,null,new LocalJoinSession.Approval(){public CompletableFuture<String> invite(String r){return new CompletableFuture<>();}public CompletableFuture<String> accept(String i){throw new AssertionError();}public CompletableFuture<Void> receipt(String r){throw new AssertionError();}public void status(String text){}},System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(25)));}assertEquals(0,sent.size());}
}
